async function switchDemoView(mode){if(!['free','subscriber','subscriber_agent','developer'].includes(mode))return;await act(async()=>{await api('/api/demo/view',{mode});chatSession=null;chatMessages=[];threadId=null;estimate=null;educationAgent='';trainingChat=[];await refresh();await render();toast('로컬 화면을 전환했습니다. 실제 결제는 없습니다.')})}
