function toggleAdd(k,on){let p=cfg.catalog.packages.find(x=>x.id===k);if(on&&p)for(let other of cfg.catalog.packages)if(other.id!==k&&selectedAdd.has(other.id)&&other.includes.some(id=>p.includes.includes(id)))selectedAdd.delete(other.id);if(on)selectedAdd.add(k);else selectedAdd.delete(k);selectedAdd=normalizeAdd(selectedAdd);render()}
function updatePrice(){if($('#quote-price'))$('#quote-price').innerHTML=`<b>예상 월 ${money(cfg.catalog.plans.find(x=>x.id===selectedPlan).price+addonTotal())}</b><br><small>교육 및 알림톡·문자 별도</small>`}
async function applyPlan(){await act(async()=>{if(selectedPlan==='free'){await api('/api/demo/billing',{plan:'free',addons:[]});await refresh();render();return}await openCheckout({kind:'subscription',plan:selectedPlan,addons:[...normalizeAdd(selectedAdd)]})})}
function features(){return pageTop('전체 기능 비교','기본 포함, 별도 구매 및 준비 중 구분')+billingTabs()+card('기본 제공',table(['기능','무료 회원','유료 구독'],[['최초 교육 20크레딧','포함','포함'],['최초 상담 테스트','1회','월 제공량'],...cfg.catalog.basic.map(n=>n==='AI 교육 (크레딧 차감)'?[n,'크레딧 차감','크레딧 차감']:[n,n==='상담 내역 열람'?'1회 테스트 기록':['말투 설정','업체명·로고','공지·구매처 안내','기본 자동·수동 설정'].includes(n)?'포함':'미제공','포함'])]))+card('추가 결제 기능',table(['기능','무료 회원','유료 구독'],cfg.catalog.addons.map(x=>[x.name,'미제공',x.local?'추가 결제':'추가 결제 · 준비 중'])))}
function credits(){return pageTop('AI 교육 크레딧','고성능 AI 분석에만 사용량 차감')+billingTabs()+card('일회성 충전',table(['요금제','크레딧','금액'],cfg.catalog.education.map(x=>[x.name,x.quantity.toLocaleString(),money(x.price)]))+`<p>보유 크레딧: ${me.credits}</p>${me.sandbox_allowed?label('충전 상품',select('edu-sku',cfg.catalog.education.filter(x=>x.price).map(x=>[x.id,x.name+' · '+money(x.price)]),'mini'))+btn('로컬 테스트 충전',"act(async()=>{await openCheckout({kind:'education',sku:val('edu-sku')})})",'primary'):'<p>실제 결제 준비 중</p>'}<p class="muted">기본 말투 설정은 무료이며, AI 교육 및 모범 답변 교육은 크레딧이 차감됩니다.</p>`)}
function addonPriceTable(headers,rows){return `<div class="wrap addon-price-table"><table><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((value,i)=>`<td data-label="${e(headers[i])}">${e(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function addons(){return pageTop('추가 기능 요금표','필요한 기능만 선택 · 월 추가 구독')+billingTabs()+[...new Set(cfg.catalog.addons.map(x=>x.group))].map(g=>card(g,addonPriceTable(['기능','월 요금','상태'],cfg.catalog.addons.filter(x=>x.group===g).map(x=>[x.name,money(x.price),x.local?'로컬 구현':'준비 중'])))).join('')+card('추가 기능 패키지',addonPriceTable(['패키지','월 요금','포함 기능'],cfg.catalog.packages.map(p=>[p.name,money(p.price),p.includes.map(i=>cfg.catalog.addons.find(x=>x.id===i)?.name).join(', ')])))+card('알림톡·SMS 별도 충전',addonPriceTable(['유형','건수','가격'],cfg.catalog.messages.map(x=>[x.name,x.quantity,money(x.price)])))}
async function render(){let id=++renderId;route=location.hash.slice(1)||'education';if(!me){$('#app').innerHTML=home();return}if(id!==renderId)return;let views={education,style,preview:()=>preview(),test:()=>preview(true),inbox,alerts,settings,calendar,fields:fieldsPage,'booking-settings':bookingSettings,customers,channels,developer,pricing,features,credits,addons,allinone,orders,agents,invites,costs};try{let html=await (views[route]||education)();if(id!==renderId)return;$('#app').innerHTML=shell(html);updatePrice()}catch(x){if(id===renderId)$('#app').innerHTML=shell(card('오류',`<p class="error">${e(x.message)}</p>${btn('다시 시도','render()')}`))}}
async function init(){try{if(location.hash.startsWith('#invite=')){sessionStorage.setItem('csai-invite',location.hash.slice(8));history.replaceState(null,'',location.pathname+'#education')}cfg=await api('/api/config');if(publicMode){pub=await api('/api/public/'+enc(slug));let saved=sessionStorage.getItem('csai-session-'+slug);if(saved){try{chatMessages=await api('/api/session/'+enc(saved)+'/messages');chatSession=saved}catch{sessionStorage.removeItem('csai-session-'+slug)}}$('#app').innerHTML=`<div class="public">${phone(pub)}</div>`;setInterval(async()=>{if(!chatSession||sending||$('#booking-box'))return;try{let ms=await api('/api/session/'+enc(chatSession)+'/messages');if(ms.length!==chatMessages.length){chatMessages=ms;$('#messages').innerHTML=`<div class="bubble">${e(pub.welcome)}</div>`+ms.map(m=>bubble(m.role,m.body)).join('');$('#messages').scrollTop=$('#messages').scrollHeight}}catch{}},4000);return}try{await refresh();selectedPlan=me.plan==='free'?'lite':me.plan;selectedAdd=new Set(me.addons);let invitation=sessionStorage.getItem('csai-invite');if(invitation){try{if(confirm('협력업체 무료 체험을 시작할까요?')){await api('/api/invites/accept',{code:invitation});await refresh();toast('무료 체험이 시작되었습니다.')}}catch(err){toast(err.message)}finally{sessionStorage.removeItem('csai-invite')}}}catch(x){if(x.status!==401)throw x}await render()}catch(x){$('#app').innerHTML=`<div class="hero"><div class="hero-inner"><h1>CS AI</h1><p class="error">${e(x.message)}</p><a href="/">처음으로</a></div></div>`}}
