const oldAlerts=alerts;alerts=async function(){let html=await oldAlerts(),ev=await api('/api/events');html+=card('업무 알림 기록',btn('모두 읽음',"act(async()=>{await api('/api/events/read',{});render()})")+ev.map(x=>`<div class="line">${x.sample?'<span class="sample-tag">샘플</span>':''}<b>${e(x.title)}</b><p class="muted">${e(new Date(x.created*1000).toLocaleString())} · ${x.seen?'읽음':'새 알림'}</p></div>`).join(''));if(has('email')){let n=await api('/api/notifications');html+=card('이메일 알림',label('수신 주소',input('notify-email',n.settings.email||n.verified_email||'','email'))+`<p class="muted">${cfg.demo?'개발 환경에서는 발송하지 않습니다.':'실제 이메일은 확인된 로그인 주소로만 발송합니다.'}</p>`+`<label><input type="checkbox" class="check" id="notify-enabled" ${n.settings.enabled?'checked':''}> 전송 활성화</label>`+btn('저장',"act(async()=>{await api('/api/notifications',{email:val('notify-email'),enabled:checked('notify-enabled')});render()})")+btn('대기 알림 보내기',"act(async()=>{let r=await api('/api/notifications/dispatch',{});toast('처리 '+r.results.length+'건');render()})",'primary')+`<p class="muted">${n.live_enabled?'실제 발송 활성화 · 검증 필요':cfg.demo?'로컬 모의 전송 · 이메일은 발송되지 않음':'실제 발송 비활성화'} / 관련 알림 옵션 필요 / ${n.auto_enabled?'자동 발송 설정 ON (워커 실행 필요)':'현재 수동 전송'}</p>`+n.deliveries.map(d=>`<div class="line">${e(d.status)} ${e(d.error)}</div>`).join(''))}return html};
